'use client';

import { useMemo, useState } from "react";
import { ClipboardCopy, Download, FileText, X } from "@/components/ui/icons";
import { useCanvasStore } from "@/store/useCanvasStore";
import { useSimStore } from "@/store/useSimStore";

/**
 * Auto-generated blameless post-mortem: distills the DVR window around the
 * active (or most recent) chaos injection into timeline, impact, root-cause
 * hypotheses ranked by error contribution, and preventive action items.
 * Exports as Markdown via clipboard or .md download.
 */

interface PostMortemModalProps {
  open: boolean;
  onClose: () => void;
}

export function PostMortemModal({ open, onClose }: PostMortemModalProps) {
  const history = useSimStore((s) => s.history);
  const chaos = useSimStore((s) => s.chaos);
  const nodes = useCanvasStore((s) => s.nodes);
  const [copied, setCopied] = useState(false);

  const report = useMemo(() => {
    if (history.length === 0) return null;
    const startTick = chaos.startedAtTick;
    const window_ = history.filter((s) => s.tick >= startTick);
    const basis = window_.length > 0 ? window_ : history;
    const peakErr = basis.reduce((a, b) => (b.globalErrorRate > a.globalErrorRate ? b : a), basis[0]!);
    const peakP99 = basis.reduce((a, b) => (b.globalP99Ms > a.globalP99Ms ? b : a), basis[0]!);
    const first = basis[0]!;
    const last = basis[basis.length - 1]!;

    const contributions = new Map<string, number>();
    for (const snap of basis) {
      for (const tele of Object.values(snap.nodes)) {
        contributions.set(tele.nodeId, (contributions.get(tele.nodeId) ?? 0) + tele.droppedRps);
      }
    }
    const ranked = [...contributions.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3)
      .map(([nodeId, dropped]) => {
        const label = String(nodes.find((n) => n.id === nodeId)?.data.label ?? nodeId);
        return { nodeId, label, dropped };
      });

    const chaosLabel = chaos.active || chaos.kind !== "none" ? chaos.kind : "unplanned incident";
    const lines = [
      `# Post-mortem: ${chaosLabel.replace(/_/g, " ")} — ${new Date().toISOString().slice(0, 10)}`,
      ``,
      `Severity: ${peakErr.globalErrorRate > 0.1 ? "SEV1" : peakErr.globalErrorRate > 0.02 ? "SEV2" : "SEV3"} (blameless)`,
      ``,
      `## Summary`,
      ``,
      `At tick ${first.tick}, ${chaosLabel.replace(/_/g, " ")} began${
        chaos.targetRegion ? ` in region ${chaos.targetRegion}` : " across the topology"
      }. Peak error burn hit ${(peakErr.globalErrorRate * 100).toFixed(2)}% at tick ${peakErr.tick}; peak p99 reached ${
        peakP99.globalP99Ms >= 1000 ? `${(peakP99.globalP99Ms / 1000).toFixed(2)}s` : `${peakP99.globalP99Ms.toFixed(0)}ms`
      } at tick ${peakP99.tick}. By tick ${last.tick}, error burn settled to ${(last.globalErrorRate * 100).toFixed(2)}%.`,
      ``,
      `## Timeline`,
      ``,
      `- t${first.tick}: incident onset — global ${first.globalRps.toFixed(0)} RPS, p99 ${
        first.globalP99Ms >= 1000 ? `${(first.globalP99Ms / 1000).toFixed(2)}s` : `${first.globalP99Ms.toFixed(0)}ms`}.`,
      `- t${peakErr.tick}: worst error burn ${(peakErr.globalErrorRate * 100).toFixed(2)}%.`,
      `- t${peakP99.tick}: worst latency p99 ${
        peakP99.globalP99Ms >= 1000 ? `${(peakP99.globalP99Ms / 1000).toFixed(2)}s` : `${peakP99.globalP99Ms.toFixed(0)}ms`}.`,
      `- t${last.tick}: steady state — ${(last.globalErrorRate * 100).toFixed(2)}% errors, ${last.globalRps.toFixed(0)} RPS served.`,
      ``,
      `## Root-cause hypotheses (ranked by dropped-RPS contribution)`,
      ``,
      ...(ranked.length > 0
        ? ranked.map(
            (r, i) => `${i + 1}. **${r.label}**: ~${r.dropped.toFixed(0)} cumulative dropped requests — check saturation (ρ), queue depth, and circuit flaps on its inbound edges.`,
          )
        : ["- No single contributor dominated; suspect correlated capacity loss rather than one hotspot."]),
      ``,
      `## Action items`,
      ``,
      `- [ ] Add autoscaling or replica headroom on ${ranked[0]?.label ?? "the top contributor"} (sustained ρ > 0.8 observed).`,
      `- [ ] Verify circuit-breaker thresholds tripped before user-visible 503s, not after.`,
      `- [ ] Schedule an Incident Arena replay of ${chaosLabel.replace(/_/g, " ")} with the same seed and confirm SLO holds.`,
      `- [ ] Attach this report to the deploy checklist for the affected services.`,
      ``,
      `_Generated by SysCanvas from ${basis.length} DVR samples. Blameless: fix systems, not people._`,
      ``,
    ];
    return { markdown: lines.join("\n"), severity: lines[2] ?? "", peakErrTick: peakErr.tick };
  }, [history, chaos, nodes]);

  if (!open) return null;

  const download = () => {
    if (!report) return;
    try {
      const blob = new Blob([report.markdown], { type: "text/markdown" });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = `postmortem-t${report.peakErrTick}.md`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(url);
    } catch {
      /* download unavailable */
    }
  };

  const copy = async () => {
    if (!report) return;
    try {
      await navigator.clipboard.writeText(report.markdown);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* clipboard blocked */
    }
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-ink/75 p-3" onClick={onClose}>
      <div
        className="max-h-[88vh] w-full max-w-2xl overflow-y-auto rounded-xl border border-zinc-700 bg-zinc-950 p-4 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label="Post-mortem report"
      >
        <div className="mb-3 flex items-center gap-2">
          <FileText size={16} className="text-zinc-300" />
          <h3 className="text-base font-bold text-zinc-50">Blameless post-mortem</h3>
          <button onClick={copy} className="ml-auto flex items-center gap-1 rounded-md border border-zinc-700 px-2 py-1.5 text-xs text-zinc-300 hover:bg-zinc-800">
            <ClipboardCopy size={13} /> {copied ? "Copied" : "Copy MD"}
          </button>
          <button onClick={download} className="flex items-center gap-1 rounded-md border border-zinc-700 px-2 py-1.5 text-xs text-zinc-300 hover:bg-zinc-800">
            <Download size={13} /> .md
          </button>
          <button onClick={onClose} className="flex h-8 w-8 items-center justify-center rounded-md border border-zinc-700 text-zinc-400 hover:bg-zinc-800" aria-label="Close post-mortem">
            <X size={16} />
          </button>
        </div>
        {!report ? (
          <p className="rounded-md border border-zinc-800 bg-zinc-900/60 p-4 text-xs text-zinc-400">
            No DVR samples yet. Run the simulation (optionally with chaos injected) to generate a report.
          </p>
        ) : (
          <pre className="whitespace-pre-wrap rounded-md border border-zinc-800 bg-zinc-900/60 p-3 font-mono text-[11px] leading-relaxed text-zinc-200">
            {report.markdown}
          </pre>
        )}
      </div>
    </div>
  );
}
